({
async finish(tab,id){
 const h=eval(load("helpers")),w=eval(load("wf"));
 const r=await tools.exec_command({cmd:"cat "+h.q("job-search/wttj-documents/"+id+".json"),max_output_tokens:18000});
 const m=JSON.parse(r.output);
 await tools.mcp__t3_code__preview_navigate({tabId:tab,url:"https://wellfound.com/profile/edit/resume"});
 const input=await h.ev(tab,"!!document.querySelector('input[type=file]')");if(!input)throw Error("Resume input unavailable");
 text(await h.upload(tab,id,"input[type=file]"));
 for(let n=0;n<4;n++){await new Promise(r=>setTimeout(r,1500));try{await w.verifyAttachment(tab,id);break;}catch(e){if(n===3)throw e;}}
 await tools.mcp__t3_code__preview_navigate({tabId:tab,url:m.url});
 await new Promise(r=>setTimeout(r,1200));
 await h.ev(tab,"(()=>{window.requestAnimationFrame=cb=>setTimeout(()=>cb(performance.now()),16);const b=document.querySelector('.styles_applyButton__7gnpI:not(.styles_desktop__ptgfw)');if(!b||b.innerText!=='Apply')throw Error('Apply unavailable or already applied');return true})()");
 const snapshot=await tools.mcp__t3_code__preview_snapshot({tabId:tab,includeImage:false});let locator=snapshot.structuredContent?.interactiveElements?.find(e=>e.tag==='button'&&e.name==='Apply')?.selector;if(!locator){const inspected=await h.ev(tab,"(()=>{const b=document.querySelector('.styles_applyButton__7gnpI:not(.styles_desktop__ptgfw)');return b&&b.innerText==='Apply'&&!b.disabled?{selector:'.styles_applyButton__7gnpI:not(.styles_desktop__ptgfw)',html:b.outerHTML}:null})()");if(!inspected)throw Error("No inspected Apply control");locator=inspected.selector;}let clicked=await tools.mcp__t3_code__preview_click({tabId:tab,selector:locator});if(clicked.isError){await new Promise(r=>setTimeout(r,800));const retry=await h.ev(tab,"!!document.querySelector('.styles_applyButton__7gnpI:not(.styles_desktop__ptgfw):not(:disabled)')");if(!retry)throw Error("Apply unavailable after initial interaction");clicked=await tools.mcp__t3_code__preview_click({tabId:tab,selector:".styles_applyButton__7gnpI:not(.styles_desktop__ptgfw)"});if(clicked.isError)throw Error(JSON.stringify(clicked));}
 await new Promise(r=>setTimeout(r,1000));
 const form=await h.ev(tab,"({text:document.querySelector('[role=dialog]')?.innerText,fields:[...document.querySelectorAll('[role=dialog] input,[role=dialog] textarea,[role=dialog] select')].filter(e=>e.type!=='hidden').map(e=>({id:e.id,type:e.type,required:e.required}))})");
 text(form);
 if(/not accepting applications from your current location|does not support the locations or timezones/i.test(form.text||""))throw Error("Native location blocker requires review");
 if(!form.text){store("oneAwaitingForm",{tab,id,url:m.url});await h.save("job-search/applications/"+id+"/one-tab-progress.json",{status:"awaiting-form",id,tab,url:m.url,attachment_verified:true});return {status:"awaiting-form",id,tab};}
 if(m.answers){
  if(form.fields.length!==Object.keys(m.answers).length||form.fields.some(f=>!(f.id in m.answers)))throw Error("Inspected custom form changed");
  for(const [field,value] of Object.entries(m.answers))await h.ev(tab,"(()=>{const e=document.getElementById("+JSON.stringify(field)+");if(!e)throw Error('Missing reviewed field');e.focus();Object.getOwnPropertyDescriptor(e.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(e,"+JSON.stringify(value)+");e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));e.blur();return {id:e.id,value:e.value}})()");
  await new Promise(r=>setTimeout(r,500));
  await h.save("job-search/applications/"+id+"/answers.json",m.answers);
  await h.save("job-search/applications/"+id+"/final-form-state-connected.json",await h.inspect(tab));
  await h.ev(tab,"(()=>{const b=[...document.querySelectorAll('button')].find(b=>b.innerText==='Send application');if(!b||b.disabled)throw Error('Submit unavailable');b.click();return true})()");
 }else{
  if(form.fields.length!==1||form.fields[0].type!=='textarea'||form.fields[0].required)throw Error("Form changed or requires further review");
  await eval(load("campaign")).send(tab,id,m.message);
 }
 let receipt=false;for(let n=0;n<4;n++){await new Promise(r=>setTimeout(r,2000));if(await w.recordReceipt(tab,id)){receipt=true;break;}}
 if(!receipt)throw Error("Submission remains unconfirmed");
 return true;
},
async close(tab){
 const availableWindow=await tools.exec_command({cmd:"osascript -e 'tell application \"System Events\" to tell process \"T3 Code (Alpha)\" to get count of windows'",max_output_tokens:100});if(availableWindow.exit_code===0&&availableWindow.output.trim()==="0"){await eval(load("helpers")).save("job-search/browser-close-pending.json",{tab,reason:"No T3 native window. Reuse this one tab; do not open another.",current_application:load("current")?.id});text({closure:"deferred",tab,tab_limit:1});return false;}
 const h=eval(load("helpers")),title=await h.ev(tab,"document.title");const pending=load("oneAwaitingForm");if(pending?.tab===tab){const checked=await tools.exec_command({cmd:"python3 -c "+h.q("import json;from pathlib import Path;p=Path('job-search/applications/"+pending.id+"/confirmation.json');print(p.exists() and json.loads(p.read_text()).get('status')=='submitted')"),max_output_tokens:100});if(checked.output.trim()!=="True")throw Error("Pending unconfirmed application must be inspected before closure");store("oneAwaitingForm",null);}
 let r=await tools.exec_command({cmd:"osascript scripts/close-career-tab-restoring-thread.applescript "+h.q(title)+" all",max_output_tokens:600});
 if(r.exit_code!==0&&r.output.includes('First panel tab differs'))r=await tools.exec_command({cmd:"osascript scripts/close-career-tab-restoring-thread.applescript 'wellfound.com' all",max_output_tokens:600});
 if(r.exit_code!==0)throw Error(r.output);text(r.output);await tools.exec_command({cmd:"python3 -c \"from pathlib import Path;Path(\'job-search/browser-close-pending.json\').unlink(missing_ok=True)\"",max_output_tokens:100});store("tab",null);return true;
}
})
